/**
 * @fileoverview Access to the data in `src/data`.
 *
 * Most of these files are generated by the scripts in `tools/`, which the
 * "Data Fetch" GitHub workflow runs every day. They are loaded as content
 * collections (see `src/content.config.ts`) so that they are validated at
 * build time.
 *
 * @author Nicholas C. Zakas
 */

//-----------------------------------------------------------------------------
// Imports
//-----------------------------------------------------------------------------

import { getCollection, getEntry, type CollectionEntry } from "astro:content";
import budget from "../data/budget.json";
import palette from "../data/palette.json";
import techsponsors from "../data/techsponsors.json";

//-----------------------------------------------------------------------------
// Types
//-----------------------------------------------------------------------------

export type Author = CollectionEntry<"authors">["data"];
export type Person = CollectionEntry<"team">["data"]["items"][number];
export type Sponsor = CollectionEntry<"sponsors">["data"]["items"][number];

//-----------------------------------------------------------------------------
// Exports
//-----------------------------------------------------------------------------

// hand-maintained data
export { budget, palette, techsponsors };

/**
 * Project statistics from `src/data/stats.json`.
 */
export async function getStats() {
	return (await getEntry("stats", "stats"))!.data;
}

/**
 * Sponsors from `src/data/sponsors.json`, grouped by tier.
 */
export async function getSponsors() {
	const tiers = await getCollection("sponsors");
	const totals = (await getEntry("sponsorTotals", "totals"))!.data;
	const tier = (id: string): Sponsor[] =>
		tiers.find(entry => entry.id === id)?.data.items ?? [];

	return {
		totals,
		diamond: tier("diamond"),
		platinum: tier("platinum"),
		gold: tier("gold"),
		silver: tier("silver"),
		bronze: tier("bronze"),
		backers: tier("backers"),
	};
}

/**
 * One-time donations from `src/data/donations.json`, most recent first.
 */
export async function getDonations() {
	const donations = await getCollection("donations");

	return donations
		.map(entry => entry.data)
		.sort((a, b) => Date.parse(b.date) - Date.parse(a.date));
}

/**
 * Team members from `src/data/team.json`, grouped by role.
 */
export async function getTeam() {
	const groups = await getCollection("team");
	const group = (id: string): Person[] =>
		groups.find(entry => entry.id === id)?.data.items ?? [];

	return {
		tsc: group("tsc"),
		reviewers: group("reviewers"),
		committers: group("committers"),
		website: group("website"),
		support: group("support"),
		alumni: group("alumni"),
	};
}

/**
 * Blog post authors from `src/data/all_authors.json`, keyed by username.
 */
export async function getAuthors(): Promise<Record<string, Author>> {
	const authors = await getCollection("authors");

	return Object.fromEntries(authors.map(entry => [entry.id, entry.data]));
}
